describe('Dark Mode Toggle from Preferences', () => {
  beforeEach(() => {
    cy.visit('/settings');
  });

  it('should successfully toggle dark mode from preferences and reflect change in UI', () => {
    // Verify initial UI is light mode
    cy.get('[data-testid="theme-toggle"]').should('be.visible');
    cy.get('[data-testid="theme-label"]').should('contain', 'Light Mode');
    cy.get('[data-testid="content-area"]').should('have.class', 'light-theme');

    // Intercept API call to save preference
    cy.intercept('POST', '/api/user/preferences/theme').as('toggleDarkMode');

    // Click the dark mode toggle button
    cy.get('[data-testid="theme-toggle"]').click();

    // Verify API was called
    cy.wait('@toggleDarkMode');

    // Verify UI reflects dark mode
    cy.get('[data-testid="theme-label"]').should('contain', 'Dark Mode');
    cy.get('[data-testid="content-area"]').should('have.class', 'dark-theme');

    // Verify dark mode styles are applied
    cy.get('[data-testid="content-area"]').should('have.css', 'background-color', '#121212');
    cy.get('[data-testid="content-area"]').should('have.css', 'color', '#ffffff');

    // Verify theme persists on page reload
    cy.reload();
    cy.get('[data-testid="theme-label"]').should('contain', 'Dark Mode');
    cy.get('[data-testid="content-area"]').should('have.class', 'dark-theme');
  });

  it('should not toggle dark mode if user has disabled it in preferences', () => {
    // Set up user preference to disable dark mode
    cy.intercept('POST', '/api/user/preferences/theme', {
      statusCode: 200,
      body: {
        enabled: false,
        theme: 'light'
      }
    }).as('disableDarkMode');

    // Verify initial UI is light mode
    cy.get('[data-testid="theme-toggle"]').should('be.visible');
    cy.get('[data-testid="theme-label"]').should('contain', 'Light Mode');

    // Attempt to toggle dark mode
    cy.get('[data-testid="theme-toggle"]').click();

    // Verify API was called but no change in UI
    cy.wait('@disableDarkMode');

    // Verify UI remains light mode
    cy.get('[data-testid="theme-label"]').should('contain', 'Light Mode');
    cy.get('[data-testid="content-area"]').should('have.class', 'light-theme');

    // Verify dark mode is still disabled
    cy.get('[data-testid="theme-label"]').should('contain', 'Dark Mode');
    cy.get('[data-testid="content-area"]').should('have.css', 'background-color', '#ffffff');
  });
});
